-- Check distinct values of support_and_resources community_resources
SELECT DISTINCT jsonb_extract_path_text(support_and_resources, 'community_resources') as community_res 
FROM facilities;

-- Let me check if the issue is with the join - maybe some patients don't have assessments
-- Let me also check how many distinct clinkeys are in the patients table
SELECT COUNT(DISTINCT clinleadref) FROM patients WHERE clinleadref IS NOT NULL;

-- Let me check if crisisint is really called "crisis intervention frequency" 
-- Maybe it should come from a different source - like assessmentsocialanddiagnosis.strslvl?
SELECT DISTINCT crisisint FROM treatmentbasics;

-- Check if there are facilities with ONLY 'None' as support_services
SELECT fackey FROM facilities 
WHERE jsonb_extract_path_text(support_and_resources, 'support_services') = 'None';

-- Check if treatmentoutcomes links back to encounters
SELECT COUNT(*) FROM treatmentbasics tb 
JOIN treatmentoutcomes to2 ON tb.txkey = to2.txref;
